import { readFileSync } from "node:fs";

import { type APIRequestContext } from "@playwright/test";

import { expect, sample, test, uniqueName } from "../../fixtures";

async function submitVendor(member: APIRequestContext, insuranceFile: string): Promise<string> {
  const created = await member.post("/api/vendors", {
    data: { name: uniqueName("Queue"), category: "services", contact_email: "ops@queue.example" },
  });
  expect(created.status(), await created.text()).toBe(201);
  const { id } = (await created.json()) as { id: string };

  const uploads = [
    ["w9", "w9.txt"],
    ["insurance_certificate", insuranceFile],
    ["contract", "contract.txt"],
  ] as const;
  for (const [kind, file] of uploads) {
    const upload = await member.post(`/api/vendors/${id}/documents`, {
      multipart: { kind, file: { name: file, mimeType: "text/plain", buffer: readFileSync(sample(file)) } },
    });
    expect(upload.status(), await upload.text()).toBe(201);
  }

  // Extraction runs in the background; wait until every document is extracted.
  await expect
    .poll(
      async () => {
        const res = await member.get(`/api/vendors/${id}/documents`);
        const docs = (await res.json()) as { status: string }[];
        return docs.length === 3 && docs.every((d) => d.status === "extracted");
      },
      { timeout: 15_000 },
    )
    .toBe(true);

  const submitted = await member.post(`/api/vendors/${id}/submit`);
  expect(submitted.status(), await submitted.text()).toBe(200);
  return id;
}

test("review queue lists the unparsed-date vendor first, ordered by lowest confidence", { tag: "@REV-03" }, async ({ apiAs }) => {
  // Arrange
  const member = await apiAs("member");
  const reviewer = await apiAs("reviewer");
  const plainId = await submitVendor(member, "insurance_certificate.txt");
  const unparsedId = await submitVendor(member, "insurance_certificate_unparseable.txt");

  // Act
  const res = await reviewer.get("/api/review-queue");
  expect(res.status(), await res.text()).toBe(200);
  const queue = (await res.json()) as { vendor_id: string; lowest_confidence: number }[];

  // Assert
  const plainIndex = queue.findIndex((item) => item.vendor_id === plainId);
  const unparsedIndex = queue.findIndex((item) => item.vendor_id === unparsedId);
  expect(plainIndex, "plain vendor is in the review queue").toBeGreaterThanOrEqual(0);
  expect(unparsedIndex, "unparsed-date vendor is in the review queue").toBeGreaterThanOrEqual(0);
  expect(unparsedIndex, "unparsed-date vendor is listed before the other").toBeLessThan(plainIndex);

  const confidences = queue.map((item) => item.lowest_confidence);
  expect(confidences, "queue is ordered by lowest confidence, ascending").toEqual(
    [...confidences].sort((a, b) => a - b),
  );
});
